// SEEDED DEFECT: teardown called synchronously inside the subscribe callback.
export function wire(supabase) {
  const ch = supabase.channel('x');
  ch.on('postgres_changes', {}, () => {}).subscribe((status) => {
    if (status === 'SUBSCRIBED') {
      supabase.removeChannel(ch);
    }
  });
  return ch;
}

// SEEDED DEFECT: raw session_coordination insert bypassing insertCoordinationRow().
export async function send(supabase, payload) {
  const { error } = await supabase.from('session_coordination').insert({
    message_type: 'INFO',
    payload
  });
  return error;
}

// SEEDED DEFECT: hardcodes a DIFFERENT literal than the migration default above,
// silently negating it at insert time (the F12 drift class).
export async function create(supabase) {
  return supabase.from('seeded_widgets').insert({ status: 'draft' });
}

// SEEDED DEFECT: gates on a raw failure-COUNT delta instead of an identity-set diff.
export function gate(prevFailCount, failCount) {
  if (failCount > prevFailCount) {
    throw new Error(`failures rose ${prevFailCount} -> ${failCount}`);
  }
  return true;
}

// SEEDED DEFECT: the raw Windows-broken direct-execution guard. argv[1] is a
// backslash path on Windows and import.meta.url is a file:// URL, so this never
// matches and the guard silently no-ops.
function main() { console.log('ran'); }
if (import.meta.url === `file://${process.argv[1]}`) main();

// SEEDED DEFECT: writes metadata.is_seeded_orphan and nothing ever reads it (ORPHAN).
export async function mark(supabase, id) {
  return supabase.from('widgets').update({ metadata: { is_seeded_orphan: true } }).eq('id', id);
}
